1	//! Version checking module for `DotState`
2	//!
3	//! This module handles checking for new versions of `DotState` from GitHub releases
4	//! and provides update information to users.
5	
6	use std::time::Duration;
7	use update_informer::{registry::GitHub, Check};
8	
9	/// GitHub repository owner
10	const REPO_OWNER: &str = "serkanyersen";
11	/// GitHub repository name
12	const REPO_NAME: &str = "dotstate";
13	
14	/// Information about an available update
15	#[derive(Debug, Clone)]
16	pub struct UpdateInfo {
17	    /// Current installed version
18	    pub current_version: String,
19	    /// Latest available version
20	    pub latest_version: String,
21	    /// URL to the release page
22	    pub release_url: String,
23	}
24	
25	impl UpdateInfo {
26	    /// Get the install.sh URL for self-update
27	    #[must_use]
28	    pub fn install_script_url() -> &'static str {
29	        "https://dotstate.serkan.dev/install.sh"
30	    }
31	
32	    /// Get the GitHub releases URL
33	    #[must_use]
34	    pub fn releases_url() -> String {
35	        format!("https://github.com/{REPO_OWNER}/{REPO_NAME}/releases")
36	    }
37	}
38	
39	/// Check for updates using update-informer
40	///
41	/// This function respects the check interval configured by the user.
42	/// Results are cached by update-informer to prevent excessive API calls.
43	///
44	/// # Arguments
45	/// * `interval_hours` - How often to check for updates (in hours)
46	///
47	/// # Returns
48	/// * `Some(UpdateInfo)` if a newer version is available
49	/// * `None` if already up to date or check failed/skipped
50	#[must_use]
51	pub fn check_for_updates(_interval_hours: u64) -> Option<UpdateInfo> {
52	    // Always do a fresh check - the TUI only calls this once at startup anyway
53	    // Using Duration::ZERO bypasses the "first run" caching behavior
54	    check_for_updates_now()
55	}
56	
57	/// Force check for updates, ignoring the cache
58	///
59	/// This is useful for the `dotstate upgrade` command where the user
60	/// explicitly wants to check for updates.
61	///
62	/// # Returns
63	/// * `Some(UpdateInfo)` if a newer version is available
64	/// * `None` if already up to date or check failed
65	pub fn check_for_updates_now() -> Option<UpdateInfo> {
66	    let current_version = env!("CARGO_PKG_VERSION");
67	    let repo = format!("{REPO_OWNER}/{REPO_NAME}");
68	
69	    // Use Duration::ZERO to skip cache and force a fresh check every time
70	    let informer = update_informer::new(GitHub, &repo, current_version).interval(Duration::ZERO);
71	
72	    match informer.check_version() {
73	        Ok(Some(new_version)) => {
74	            let version_str = new_version.to_string();
75	            // version_str already includes 'v' prefix from GitHub tags
76	            Some(UpdateInfo {
77	                current_version: current_version.to_string(),
78	                latest_version: version_str.clone(),
79	                release_url: format!(
80	                    "https://github.com/{REPO_OWNER}/{REPO_NAME}/releases/tag/{version_str}"
81	                ),
82	            })
83	        }
84	        Ok(None) => None,
85	        Err(e) => {
86	            // Log full error details for debugging
87	            let error_msg = e.to_string();
88	            tracing::debug!(
89	                "Update check failed - error: '{}', error kind: {:?}, source: {:?}",
90	                error_msg,
91	                e,
92	                e.source()
93	            );
94	            None
95	        }
96	    }
97	}
98	
99	/// Check for updates and return a Result to distinguish errors from "no updates"
100	///
101	/// # Returns
102	/// * `Ok(Some(UpdateInfo))` if a newer version is available
103	/// * `Ok(None)` if already up to date
104	/// * `Err(String)` if the check failed
105	pub fn check_for_updates_with_result() -> Result<Option<UpdateInfo>, String> {
106	    let current_version = env!("CARGO_PKG_VERSION");
107	    let repo = format!("{REPO_OWNER}/{REPO_NAME}");
108	
109	    // Use Duration::ZERO to skip cache and force a fresh check every time
110	    let informer = update_informer::new(GitHub, &repo, current_version).interval(Duration::ZERO);
111	
112	    match informer.check_version() {
113	        Ok(Some(new_version)) => {
114	            let version_str = new_version.to_string();
115	            // version_str already includes 'v' prefix from GitHub tags
116	            Ok(Some(UpdateInfo {
117	                current_version: current_version.to_string(),
118	                latest_version: version_str.clone(),
119	                release_url: format!(
120	                    "https://github.com/{REPO_OWNER}/{REPO_NAME}/releases/tag/{version_str}"
121	                ),
122	            }))
123	        }
124	        Ok(None) => Ok(None),
125	        Err(e) => {
126	            let error_msg = format!("{e}");
127	            let mut error_details = error_msg.clone();
128	
129	            // Include source error if available
130	            if let Some(source) = e.source() {
131	                let source_str = source.to_string();
132	                error_details.push_str(": ");
133	                error_details.push_str(&source_str);
134	
135	                // Detect if it's a timeout (could be client or server-side)
136	                if source_str.contains("timed out") || error_msg.contains("timeout") {
137	                    tracing::debug!(
138	                        "Update check timed out (GitHub API may be slow or unavailable)"
139	                    );
140	                } else {
141	                    tracing::debug!("Update check failed: {}", error_details);
142	                }
143	            } else {
144	                tracing::debug!("Update check failed: {}", error_details);
145	            }
146	
147	            Err(error_details)
148	        }
149	    }
150	}
