//! Regression tests for the Settings screen.
//!
//! Tests cover:
//! - Label synchronization between SettingItem::name() and apply_setting_by_name()
//! - Settings can be applied without errors
//! - UpdateCheck setting specifically with new "Automatic Update Checks" label

#[cfg(test)]
mod settings_tests {
    use dotstate::config::{Config, RepoMode};
    use dotstate::screens::settings::{SettingItem, SettingsScreen};
    use tempfile::TempDir;

    /// Create a test config
    fn create_test_config(repo_mode: RepoMode) -> Config {
        let temp_dir = TempDir::new().unwrap();
        let config_path = temp_dir.path().join("test_config.toml");

        let mut config = Config::load_or_create(&config_path).unwrap();
        config.repo_mode = repo_mode;
        config
    }

    #[test]
    fn test_all_setting_names_are_unique() {
        let config = create_test_config(RepoMode::GitHub);
        let all_items = SettingItem::all(config.repo_mode);

        let names: Vec<&str> = all_items.iter().map(|item| item.name()).collect();
        let unique_count = names.iter().collect::<std::collections::HashSet<_>>().len();

        assert_eq!(
            unique_count, names.len(),
            "Setting names should be unique, found duplicates: {:?}",
            names
        );
    }

    #[test]
    fn test_setting_name_label_matches_apply_path() {
        let mut config = create_test_config(RepoMode::GitHub);
        let all_items = SettingItem::all(config.repo_mode);

        // For each setting, ensure:
        // 1. The display name is defined in name()
        // 2. The display name can be applied in apply_setting_to_config()
        for item in all_items {
            let name = item.name();

            // Test applying the first option (index 0) with this setting's name
            let result = SettingsScreen::new().apply_setting_to_config(
                &mut config,
                name,
                0, // First option
            );

            assert!(
                result,
                "Setting name '{}' from SettingItem::{:?} should be valid in apply_setting_by_name()",
                name, item
            );
        }
    }

    #[test]
    fn test_automatic_update_checks_label() {
        let mut config = create_test_config(RepoMode::GitHub);
        let screen = SettingsScreen::new();

        // Verify the CheckForUpdates setting uses the correct new label
        let check_updates = SettingItem::CheckForUpdates;
        assert_eq!(
            check_updates.name(),
            "Automatic Update Checks",
            "CheckForUpdates setting should be labeled 'Automatic Update Checks'"
        );

        // Verify the label is accepted by apply_setting_to_config
        let result = screen.apply_setting_to_config(
            &mut config,
            "Automatic Update Checks",
            0, // Enable updates
        );

        assert!(
            result,
            "Setting 'Automatic Update Checks' should be recognized in apply_setting_to_config()"
        );
    }

    #[test]
    fn test_automatic_update_checks_enable_disable() {
        let mut config = create_test_config(RepoMode::GitHub);
        let screen = SettingsScreen::new();

        // Test enabling automatic update checks
        assert!(config.updates.check_enabled || !config.updates.check_enabled); // baseline
        let initial = config.updates.check_enabled;

        // Apply "Enable" option (index 0)
        let result = screen.apply_setting_to_config(
            &mut config,
            "Automatic Update Checks",
            0,
        );
        assert!(result, "Should successfully apply Enabled option");
        assert!(config.updates.check_enabled, "Enabled option should set check_enabled to true");

        // Apply "Disable" option (index 1)
        let result = screen.apply_setting_to_config(
            &mut config,
            "Automatic Update Checks",
            1,
        );
        assert!(result, "Should successfully apply Disabled option");
        assert!(!config.updates.check_enabled, "Disabled option should set check_enabled to false");
    }

    #[test]
    fn test_old_label_no_longer_works() {
        let mut config = create_test_config(RepoMode::GitHub);
        let screen = SettingsScreen::new();

        // Verify that the old label "Check for Updates" no longer works
        let result = screen.apply_setting_to_config(
            &mut config,
            "Check for Updates",
            0,
        );

        assert!(
            !result,
            "Old label 'Check for Updates' should no longer be recognized (breaking change is intentional)"
        );
    }

    #[test]
    fn test_setting_index_consistency() {
        let config = create_test_config(RepoMode::GitHub);

        // Verify CheckForUpdates is at the expected index
        let all_items = SettingItem::all(config.repo_mode);
        let check_updates_index = all_items.iter().position(|item| *item == SettingItem::CheckForUpdates);

        assert!(
            check_updates_index.is_some(),
            "CheckForUpdates should be in the settings list"
        );

        // Verify we can retrieve it by index
        let check_updates_idx = check_updates_index.unwrap();
        let retrieved = SettingItem::from_index(check_updates_idx, config.repo_mode);
        assert_eq!(
            retrieved, Some(SettingItem::CheckForUpdates),
            "Should be able to retrieve CheckForUpdates by its index"
        );
    }

    #[test]
    fn test_all_settings_have_non_empty_names() {
        let config = create_test_config(RepoMode::GitHub);
        let all_items = SettingItem::all(config.repo_mode);

        for item in all_items {
            let name = item.name();
            assert!(
                !name.is_empty(),
                "SettingItem::{:?} should have a non-empty name",
                item
            );
        }
    }

    #[test]
    fn test_github_mode_includes_embed_credentials() {
        let config = create_test_config(RepoMode::GitHub);
        let all_items = SettingItem::all(config.repo_mode);
        let has_embed_creds = all_items.iter().any(|item| *item == SettingItem::EmbedCredentials);
        assert!(
            has_embed_creds,
            "GitHub mode should include EmbedCredentials setting"
        );
    }

    #[test]
    fn test_non_github_mode_excludes_embed_credentials() {
        let config = create_test_config(RepoMode::Local);
        let all_items = SettingItem::all(config.repo_mode);
        let has_embed_creds = all_items.iter().any(|item| *item == SettingItem::EmbedCredentials);
        assert!(
            !has_embed_creds,
            "Non-GitHub mode should not include EmbedCredentials setting"
        );
    }

    #[test]
    fn test_all_other_settings_unchanged() {
        let config = create_test_config(RepoMode::GitHub);
        let all_items = SettingItem::all(config.repo_mode);

        // Verify that other settings still have their original labels
        let expected_labels = vec![
            ("Theme", SettingItem::Theme),
            ("Icon Set", SettingItem::IconSet),
            ("Keymap Preset", SettingItem::KeymapPreset),
            ("Backups", SettingItem::Backups),
            ("Token in Remote URL", SettingItem::EmbedCredentials),
        ];

        for (expected_label, item) in expected_labels {
            if all_items.contains(&item) {
                assert_eq!(
                    item.name(),
                    expected_label,
                    "Setting {:?} label should not have changed",
                    item
                );
            }
        }
    }
}

